SELECT ,
EXISTS ( SELECT 1 FROM playlist_saves ps WHERE ps.playlist_id = p.id AND ps.member_id = #{viewerMemberId} )
FALSE
AS saved FROM playlists p WHERE p.deleted_at IS NULL AND ( p.visibility = 'PUBLIC' OR p.playlist_type = 'OFFICIAL'
OR p.owner_id = #{viewerMemberId}
)
AND p.owner_id = #{ownerId}
ORDER BY p.created_at DESC, p.id DESC
